<?php declare(strict_types=1);
$shownCandidates=$sepaState['candidates']['rows']??[];$shownIds=array_column($shownCandidates,'id');
?>
<fieldset data-sepa-candidates><legend><?=e($snt('Beitragsrechnungen bewusst auswählen'))?></legend><p><?=e($snt('Offene Beitragsforderungen mit gültigem persönlichem Mandat können über ihren tatsächlichen Restbetrag eingezogen werden. Bereits bezahlte Anteile bleiben erhalten. Die vollständige Prüfung erfolgt in der Vorschau.'))?></p>
<label><?=e($snt('Ganze Beitragsrechnungssuche'))?><?php $snfield('sepa_candidate_q',$snraw($_POST,'sepa_candidate_q',$snraw($_GET,'sepa_candidate_q')),$readonly);?></label><label><?=e($snt('Beitragsrechnungsseite'))?><?php $snfield('sepa_candidate_page',$snraw($_POST,'sepa_candidate_page',$snraw($_GET,'sepa_candidate_page','1')),$readonly);?></label><button class="btn btn-outline theme-secondary" name="sepa_intent" value="selection"<?=$readonly?' disabled':''?>><?=e($snt('Ganze Rechnungssuche und Seite anzeigen'))?></button>
<?php if($list=$sepaState['candidates']):?><p><?=e($snt('Gefundene Beitragsrechnungen'))?>: <?=e((string)$list['total'])?></p><?php if($list['page']!==null):?><p><?=e(strtr($snt('Seite {page} von {pages}'),['{page}'=>(string)$list['page'],'{pages}'=>(string)$list['pages']]))?></p><?php endif ?><?php endif ?>
<?php foreach($shownCandidates as$row):$checked=in_array($row['id'],$raw['data']['entries'],true);$eligible=in_array($row['payment_state'],['open','partial'],true)&&(int)$row['remaining_cents']>0;?><label class="card general-settings-check" data-sepa-candidate="<?=e($row['id'])?>"><input class="check" type="checkbox" name="data[entries][]" value="<?=e($row['id'])?>"<?=$checked?' checked':''?><?=($readonly||(!$eligible&&!$checked))?' disabled':''?>><span><strong><?=e($row['display_number'])?></strong><pre><?="\n".e($row['counterparty'])?></pre><?=e($snt('Noch einzuziehen'))?>: <?=e(euro($row['remaining_cents']))?><?php if((int)$row['allocated_cents']>0):?><p data-sepa-candidate-funding><?=e($snt('Ursprünglicher Rechnungsbetrag'))?>: <?=e(euro($row['amount_cents']))?> · <?=e($snt('Bereits bezahlt'))?>: <?=e(euro($row['allocated_cents']))?></p><?php endif ?><?php if(!$eligible):?><p><?=e($snt('Zahlungsstand zuerst prüfen; derzeit nicht für einen neuen Einzug geeignet.'))?></p><?php endif ?></span></label><?php endforeach ?>
<h3><?=e($snt('Ganze eigene Rechnungsauswahl'))?>: <?=e((string)count($raw['data']['entries']))?></h3>
<?php foreach($raw['data']['entries']as$entry):if(in_array($entry,$shownIds,true))continue;$selected=$sepaState['selected'][$entry]??null;?><label class="card general-settings-check"><input class="check" type="checkbox" name="data[entries][]" value="<?=e($entry)?>" checked<?=$readonly?' disabled':''?>><span><?php if($selected):?><strong><?=e($selected['display_number'])?></strong><pre><?="\n".e($selected['counterparty'])?></pre><?=e($snt('Noch einzuziehen'))?>: <?=e(euro((int)$selected['remaining_cents']))?><?php else:?><p><?=e($snt('Ausgewählte Rechnung nicht verfügbar. Ursprüngliche Auswahl prüfen oder bewusst entfernen.'))?></p><pre><?="\n".e($entry)?></pre><?php endif ?></span></label><?php endforeach ?>
<?php if(!$readonly):?><button class="btn btn-outline theme-secondary" name="sepa_candidate_move" value="all" formaction="<?=e($snurl(['sepa_selection'=>'1']))?>"><?=e($snt('Alle geeigneten Rechnungen dieser Seite zur Auswahl hinzufügen'))?></button><button class="btn btn-outline theme-secondary" name="sepa_candidate_move" value="clear" formaction="<?=e($snurl(['sepa_selection'=>'1']))?>"><?=e($snt('Ganze eigene Rechnungsauswahl leeren'))?></button><?php endif ?>
</fieldset>
